    var NSOPWOfflineForm = {};

    document.addEventListener("DOMContentLoaded", function (event) {
        (function ($, NSOPWOfflineForm) {

            const offLineUrl = `https://nsopw-api.ojp.gov/nsopw/v5/v1.0/jurisdictions/offline`;
            //const offLineUrl = `https://uatnsopw-api.ojp.gov/nsopw/v1/v1.0/jurisdictions/offline`;

            let url = (window.location != window.parent.location)
                ? decodeURI(document.referrer)
                : decodeURI(document.location.href);

            function getUrlVars() {
                var vars = {};
                var parts = url.replace(/[?&]+([^=&]+)=([^&]*)/gi, function (m, key, value) {
                    vars[key] = value;
                });
                return vars;
            }

            function getUrlParam(parameter, defaultvalue) {
                var urlparameter = defaultvalue;
                if (url.indexOf(parameter) > -1) {
                    urlparameter = getUrlVars()[parameter];
                }
                return urlparameter;
            }

            function emptyIfNull(val, replaceVal) {
                replaceVal = replaceVal || ""
                if (val == undefined)
                    val = replaceVal;
                return val;
            }

            const dateTimeFormat = new Intl.DateTimeFormat('en-US');

            function showErrors(flag) {
                if (flag == true) {
                    $("#errors").css("visibility", "visible");
                    $("#errors").css("height", "100%");
                    $("#errors").show();
                    return;
                }
                $("#errors").empty();
                $("#errors").css("visibility", "hidden");
                $("#errors").css("height", "0px");
                $("#errors").hide();
            }

            async function getAndBuildErrorsDiv(errorText) {
                //let message = "";
                showErrors(false);
                try {

                        let txt = `<div class="usa-alert usa-alert--error" role="contentinfo" aria-label="info"><div class='usa-alert__body'><h3 class='usa-alert__heading'>Error</h3><p class='usa-alert_text'>${errorText}</p></div></div>`;
                        $("#errors").append(txt);
                        showErrors(true);

                    //return result;
                } catch (error) {
                    //console.error(error);
                    showErrors(false);;
                }
            }

            async function getAndBuildOfflineJurisdictionsDiv() {
                let jurisdictionArray = [];
                let result = "";
                showOfflineJurisdictions(false);
                try {
                    result = await $.ajax({
                        url: offLineUrl,
                        type: "GET",
                        cache: true,
                        data: {

                        }
                    });
                    for (let i = 0; i < result.length; i++) {

                        jurisdictionArray.push(result[i].jurisdiction.name);
                    }
                    if (jurisdictionArray.length > 0) {
                        let txt = `<div class="usa-alert usa-alert--info" role="contentinfo" aria-label="info"><div class='usa-alert__body'><h3 class='usa-alert__heading'>Services Down</h3><p class='usa-alert_text'>The following jurisdiction(s): ${jurisdictionArray.join(', ')} are temporarily unavailable.</p></div></div>`;
                        $("#offlinejurisdictions").append(txt);
                        showOfflineJurisdictions(true);
                    }

                } catch (error) {

                    getAndBuildErrorsDiv("We are experiencing intermittent issues, please try again later.");
                }
            }

            function showOfflineJurisdictions(flag) {
                if (flag == true) {
                    $("#offlinejurisdictions").css("visibility", "visible");
                    $("#offlinejurisdictions").css("height", "100%");
                    $("#offlinejurisdictions").show();
                    return;
                }
                $("#offlinejurisdictions").empty();
                $("#offlinejurisdictions").css("visibility", "hidden");
                $("#offlinejurisdictions").css("height", "0px");
                $("#offlinejurisdictions").hide();
            }

            getAndBuildOfflineJurisdictionsDiv()

        })(jQuery, NSOPWOfflineForm);
    }); 	












