    document.addEventListener("DOMContentLoaded", function (event) {
        (function ($, NSOPWHistoricalCount) {

            //const historyCountUrl = `https://nsopw-api.ojp.gov/nsopw/v5/v1.1/history`;
            const historyCountUrl = '/nsopw-api/total-searches';  // cached DEx endpoint

            let url = (window.location != window.parent.location)
                ? decodeURI(document.referrer)
                : decodeURI(document.location.href);

            function getUrlVars() {
                var vars = {};
                var parts = url.replace(/[?&]+([^=&]+)=([^&]*)/gi, function (m, key, value) {
                    vars[key] = value;
                });
                return vars;
            }

            function getUrlParam(parameter, defaultvalue) {
                var urlparameter = defaultvalue;
                if (url.indexOf(parameter) > -1) {
                    urlparameter = getUrlVars()[parameter];
                }
                return urlparameter;
            }

            function emptyIfNull(val, replaceVal) {
                replaceVal = replaceVal || ""
                if (val == undefined)
                    val = replaceVal;
                return val;
            }

            function numberWithCommas(x) {
                return x.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
            }

            const dateTimeFormat = new Intl.DateTimeFormat('en-US');

            async function updateHeroBannerWithCount() {
                try {
                    result = await $.ajax({
                        url: historyCountUrl,
                        type: "GET",
                        cache: true,
                        data: {

                        }
                    });  
//                    $(".hero__subtitle").append("<div class='historical-count'>5,456,789 searches since 1/1/2024</div>");                  
                    $(".hero__subtitle").append(`<div class='historical-count'>${numberWithCommas(result.totalSearches)} searches since ${new Date(result.startDate).toLocaleDateString()}. <a href="/about-nsopw/historical-search-data" style="margin-left: 5px; color: #ffffff;">See more</a></div>`);
                } catch (error) {
                    // No need to display an error if API is down
                }

            }

            updateHeroBannerWithCount();

        })(jQuery, NSOPWHistoricalCount);
    }); 	
















